import { Attributes, registerEnum } from "@serenity-is/corelib";
import { EditorSampleDialog } from "../../Common/EditorSampleDialog";
import { SampleInfo } from "../../Common/SampleInfo";
import { ChoiceEditorsForm } from "../../ServerTypes/ChoiceEditorsForm";

/** Values of the checkbox list. An enum generated by Sergen would register itself the same way. */
export enum DeliveryDay { Monday = 1, Tuesday = 2, Wednesday = 3, Thursday = 4, Friday = 5 }
registerEnum(DeliveryDay, "Demo.DeliveryDay");

export default function pageInit() {
    SampleInfo({
        uses: ["BooleanSwitchEditor", "YesNoEditor", "CheckboxButtonEditor"]
    });

    new ChoiceEditorsDialog({}).mount();
}

export class ChoiceEditorsDialog extends EditorSampleDialog {
    static override [Symbol.typeInfo] = this.registerClass("Bizeka.Demo.ChoiceEditorsDialog", [Attributes.panel]);

    protected override getFormKey() { return ChoiceEditorsForm.formKey; }

    protected override loadInitialEntity() {
        this.propertyGrid.load({ SendSummary: true, CustomerVisible: null, DeliveryDays: "1,3,5" });
    }
}
